#include <iostream>
#include <fstream>
#include <string>

using namespace std;

int countWords(string filename) {
    int count = 0;
    ifstream file(filename);
    string word;
    while (getline(file, word)) {
        if (word.find(word) != string::npos) {
            count++;
        }
    }
    file.close();
    return count;
}

int main() {
